/// <summary>
///     The <c>AVAReturnTable_AVADistributeTargetAmountBtn_Extension</c> class is the extension of FormControl <c>AVADistributeTargetAmount</c> in form <c>ReturnTable</c>
/// </summary>
[ExtensionOf(formControlStr(ReturnTable, AVADistributeTargetAmount))]
final class AVAReturnTable_AVADistributeTargetAmountBtn_Extension
{
}

Method.Source:
/// <summary>
///    AVA <c>Clicked</c> class.
/// </summary>
public void clicked()
{
    Args                            locArgs;
    FormDataSource                  locFDSSalesTable;
    FormDataSource                  locFDSSalesLine;
    SalesTable                      locSalesTable;
    AVADistributeRedemptionAmount   locAVADistributeRedemptionAmount;

    locFDSSalesTable = element.SalesTable_DS;
    locFDSSalesLine = element.SalesLine_DS;

    next clicked();

    locSalesTable   = locFDSSalesTable.cursor();
    locArgs         = new Args();
    locArgs.caller(this.formRun());
    locArgs.record(locSalesTable);

    locAVADistributeRedemptionAmount = AVADistributeRedemptionAmount::newFromArgs(locArgs);
    if(locAVADistributeRedemptionAmount.run())
    {
        locFDSSalesLine.research(true);
        locFDSSalesLine.refresh();
    }
}
